/**
 * The Ideal Gas Law simulation.
 *
 * P = n R T / V     (R = 8.314 J/(mol*K), the real gas constant)
 *
 * One formula, no branching case: Boyle's law (P up as V down), Gay-
 * Lussac's law (P up as T up) and Avogadro's law (P up as n up) are all
 * just this same relationship holding two variables fixed. Like
 * circuits.js/coulombs-law.js/buoyancy.js/refraction.js/calorimetry.js,
 * there is no time axis and no run loop: values are recomputed live on
 * every control change. Always computed here, in code -- never fetched
 * from a server and never generated by AI. Mirrors
 * apps/physics/simulations_ideal_gas_law.py exactly (same bounds, same
 * gas constant, same formula). This file owns its own physics, SVG and
 * controls; it shares only the registry shell in lab.js.
 */
(function (window, document) {
  "use strict";

  var GAS_CONSTANT = 8.314;
  var MIN_MOLES = 0.1;
  var MAX_MOLES = 10.0;
  var MIN_TEMPERATURE_K = 100.0;
  var MAX_TEMPERATURE_K = 1000.0;
  var MIN_VOLUME_M3 = 0.001;
  var MAX_VOLUME_M3 = 1.0;

  function clampMoles(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_MOLES, Math.min(MAX_MOLES, n));
  }
  function clampTemperature(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_TEMPERATURE_K, Math.min(MAX_TEMPERATURE_K, n));
  }
  function clampVolume(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_VOLUME_M3, Math.min(MAX_VOLUME_M3, n));
  }

  function computeState(moles, temperatureK, volumeM3) {
    var n = clampMoles(moles);
    var t = clampTemperature(temperatureK);
    var v = clampVolume(volumeM3);
    var pressure = (n * GAS_CONSTANT * t) / v;
    return { moles: n, temperature: t, volume: v, pressure: pressure };
  }

  function readNum(el, name, fallback) {
    var raw = el.getAttribute("data-" + name);
    var value = parseFloat(raw);
    return isFinite(value) ? value : fallback;
  }

  function createIdealGasLawSim(root, config, lab) {
    var state = {
      moles: clampMoles(readNum(root, "moles", 1)),
      temperature: clampTemperature(readNum(root, "temperature", 298)),
      volume: clampVolume(readNum(root, "volume", 0.0245))
    };
    var computed = computeState(state.moles, state.temperature, state.volume);

    var el = {
      scene: root.querySelector("[data-lab-scene]"),
      sceneDesc: root.querySelector("[data-scene-desc]"),
      piston: root.querySelector("[data-piston]"),
      gasFill: root.querySelector("[data-gas-fill]"),
      sceneStatus: root.querySelector("[data-scene-status]"),
      graph: root.querySelector("[data-lab-graph]"),
      graphDesc: root.querySelector("[data-graph-desc]"),
      curve: root.querySelector("[data-lab-curve]"),
      marker: root.querySelector("[data-lab-marker]"),
      valueMoles: root.querySelector("[data-value-moles]"),
      valueTemperature: root.querySelector("[data-value-temperature]"),
      valueVolume: root.querySelector("[data-value-volume]"),
      valuePressure: root.querySelector("[data-value-pressure]"),
      eqPressure: root.querySelector("[data-eq-pressure]"),
      outMoles: root.querySelector("[data-out-moles]"),
      outTemperature: root.querySelector("[data-out-temperature]"),
      outVolume: root.querySelector("[data-out-volume]"),
      inputMoles: root.querySelector("[data-input-moles]"),
      inputTemperature: root.querySelector("[data-input-temperature]"),
      inputVolume: root.querySelector("[data-input-volume]"),
      btnReset: root.querySelector("[data-action-reset]")
    };

    function recompute() {
      computed = computeState(state.moles, state.temperature, state.volume);
    }

    function setMoles(value) {
      state.moles = clampMoles(value);
      if (el.inputMoles) el.inputMoles.value = String(state.moles);
      if (el.outMoles) el.outMoles.textContent = String(state.moles);
      recompute();
      render();
    }
    function setTemperature(value) {
      state.temperature = clampTemperature(value);
      if (el.inputTemperature) el.inputTemperature.value = String(state.temperature);
      if (el.outTemperature) el.outTemperature.textContent = String(state.temperature);
      recompute();
      render();
    }
    function setVolume(value) {
      state.volume = clampVolume(value);
      if (el.inputVolume) el.inputVolume.value = String(state.volume);
      if (el.outVolume) el.outVolume.textContent = String(state.volume);
      recompute();
      render();
    }
    function reset() {
      setMoles(1);
      setTemperature(298);
      setVolume(0.0245);
    }

    // Volume spans three orders of magnitude (0.001 to 1.0 m^3), so the
    // piston position uses a log scale for a readable picture -- display
    // only, never fed back into the physics.
    function volumeToPistonY(v) {
      var logMin = Math.log(MIN_VOLUME_M3), logMax = Math.log(MAX_VOLUME_M3);
      var frac = (Math.log(v) - logMin) / (logMax - logMin);
      return 190 - frac * 150; // 190 (small V) .. 40 (large V)
    }

    function renderScene() {
      var pistonY = volumeToPistonY(state.volume);
      if (el.piston) el.piston.setAttribute("y1", pistonY.toFixed(1));
      if (el.piston) el.piston.setAttribute("y2", pistonY.toFixed(1));
      if (el.gasFill) {
        el.gasFill.setAttribute("y", pistonY.toFixed(1));
        el.gasFill.setAttribute("height", (190 - pistonY).toFixed(1));
      }
      var text =
        state.moles.toFixed(1) + " moles of gas at " + state.temperature.toFixed(0) +
        " kelvin, in " + state.volume.toFixed(4) + " cubic metres. Pressure: " +
        computed.pressure.toFixed(0) + " pascals.";
      if (el.scene) el.scene.setAttribute("aria-label", text);
      if (el.sceneDesc) el.sceneDesc.textContent = text;
    }

    function renderGraph() {
      if (!el.curve) return;
      var w = 360, h = 190, left = 44, top = 12, bottom = 24, right = 12;
      var plotW = w - left - right, plotH = h - top - bottom;
      var logMin = Math.log(MIN_VOLUME_M3), logMax = Math.log(MAX_VOLUME_M3);
      var samples = 40;
      var maxP = 0;
      var points = [];
      for (var i = 0; i <= samples; i++) {
        var logV = logMin + ((logMax - logMin) * i) / samples;
        var v = Math.exp(logV);
        var c = computeState(state.moles, state.temperature, v);
        points.push([v, c.pressure]);
        if (c.pressure > maxP) maxP = c.pressure;
      }
      maxP = Math.max(maxP, 1e-9);
      var path = points.map(function (p) {
        var frac = (Math.log(p[0]) - logMin) / (logMax - logMin);
        var px = left + frac * plotW;
        var py = top + plotH - (p[1] / maxP) * plotH;
        return px.toFixed(1) + "," + py.toFixed(1);
      }).join(" ");
      el.curve.setAttribute("points", path);
      if (el.marker) {
        var mFrac = (Math.log(state.volume) - logMin) / (logMax - logMin);
        var mx = left + mFrac * plotW;
        var my = top + plotH - (computed.pressure / maxP) * plotH;
        el.marker.setAttribute("cx", mx.toFixed(1));
        el.marker.setAttribute("cy", my.toFixed(1));
      }
      var graphText =
        "Pressure versus volume, at " + state.moles.toFixed(1) + " moles and " +
        state.temperature.toFixed(0) + " kelvin -- Boyle's law, an inverse relationship.";
      if (el.graph) el.graph.setAttribute("aria-label", graphText);
      if (el.graphDesc) el.graphDesc.textContent = graphText;
    }

    function render() {
      if (el.valueMoles) el.valueMoles.textContent = state.moles.toFixed(1);
      if (el.valueTemperature) el.valueTemperature.textContent = state.temperature.toFixed(0);
      if (el.valueVolume) el.valueVolume.textContent = state.volume.toFixed(4);
      if (el.valuePressure) el.valuePressure.textContent = computed.pressure.toFixed(1);
      if (el.eqPressure) el.eqPressure.textContent = computed.pressure.toFixed(1);
      renderScene();
      renderGraph();
      root.dispatchEvent(new CustomEvent("lab:state", { detail: getState() }));
    }

    function getState() {
      return {
        moles: state.moles,
        temperatureK: state.temperature,
        volumeM3: state.volume,
        pressurePa: computed.pressure,
        running: false
      };
    }

    if (el.inputMoles) {
      el.inputMoles.addEventListener("input", function () { setMoles(el.inputMoles.value); });
      el.inputMoles.addEventListener("change", function () { setMoles(el.inputMoles.value); });
    }
    if (el.inputTemperature) {
      el.inputTemperature.addEventListener("input", function () { setTemperature(el.inputTemperature.value); });
      el.inputTemperature.addEventListener("change", function () { setTemperature(el.inputTemperature.value); });
    }
    if (el.inputVolume) {
      el.inputVolume.addEventListener("input", function () { setVolume(el.inputVolume.value); });
      el.inputVolume.addEventListener("change", function () { setVolume(el.inputVolume.value); });
    }
    if (el.btnReset) el.btnReset.addEventListener("click", reset);

    recompute();
    render();

    var api = {
      setMoles: setMoles,
      setTemperature: setTemperature,
      setVolume: setVolume,
      reset: reset,
      getState: getState
    };
    root.labInstance = api;
    return api;
  }

  PhysicsLab.register("ideal_gas_law", createIdealGasLawSim);

  PhysicsLab.IdealGasLaw = {
    GAS_CONSTANT: GAS_CONSTANT,
    MIN_MOLES: MIN_MOLES,
    MAX_MOLES: MAX_MOLES,
    MIN_TEMPERATURE_K: MIN_TEMPERATURE_K,
    MAX_TEMPERATURE_K: MAX_TEMPERATURE_K,
    MIN_VOLUME_M3: MIN_VOLUME_M3,
    MAX_VOLUME_M3: MAX_VOLUME_M3,
    clampMoles: clampMoles,
    clampTemperature: clampTemperature,
    clampVolume: clampVolume,
    computeState: computeState
  };
})(window, document);
